from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 0, 5), 'fixture 1'
assert solve([], 1) == Report(0, 0, 1), 'fixture 2'
assert solve([Entry(1, 1)], 2) == Report(0, 0, 2), 'fixture 3'
assert solve([Entry(2, 1), Entry(2, 2)], 3) == Report(0, 1, 1), 'fixture 4'
assert solve([Entry(2, 0), Entry(1, 0), Entry(3, 1)], 4) == Report(2, 1, 1), 'fixture 5'
assert solve([Entry(2, 2), Entry(1, 3), Entry(1, 3), Entry(2, 0)], 5) == Report(1, 2, 1), 'fixture 6'
assert solve([Entry(4, 4), Entry(5, 1), Entry(0, 1), Entry(0, 3), Entry(5, 1)], 6) == Report(2, 2, 2), 'fixture 7'
assert solve([Entry(6, 4), Entry(3, 5), Entry(2, 3), Entry(6, 5), Entry(4, 4), Entry(4, 0)], 7) == Report(2, 2, 3), 'fixture 8'
assert solve([Entry(4, 1), Entry(2, 0), Entry(6, 6), Entry(6, 0), Entry(7, 2), Entry(0, 0), Entry(3, 6)], 8) == Report(3, 1, 3), 'fixture 9'
assert solve([Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 0)], 1) == Report(0, 0, 1), 'fixture 10'
assert solve([Entry(1, 0), Entry(1, 1), Entry(0, 0), Entry(0, 1), Entry(1, 1), Entry(0, 0), Entry(0, 0), Entry(0, 0), Entry(0, 1)], 2) == Report(0, 0, 0), 'fixture 11'
assert solve([Entry(2, 1), Entry(0, 1), Entry(2, 2), Entry(1, 0), Entry(0, 1), Entry(1, 2), Entry(2, 1), Entry(2, 1), Entry(0, 2), Entry(1, 1)], 3) == Report(0, 0, 0), 'fixture 12'
assert solve([Entry(0, 2), Entry(3, 1), Entry(1, 1), Entry(1, 1), Entry(1, 1), Entry(1, 3), Entry(2, 2), Entry(2, 1), Entry(0, 2), Entry(1, 2), Entry(1, 0)], 4) == Report(0, 0, 1), 'fixture 13'
assert solve([Entry(0, 3), Entry(3, 0), Entry(3, 1), Entry(0, 3), Entry(4, 3), Entry(3, 2), Entry(1, 3), Entry(3, 3), Entry(2, 0), Entry(1, 3), Entry(2, 0), Entry(1, 1)], 5) == Report(1, 0, 0), 'fixture 14'
assert solve([], 6) == Report(0, 0, 6), 'fixture 15'
assert solve([Entry(4, 6)], 7) == Report(1, 1, 5), 'fixture 16'
assert solve([Entry(5, 6), Entry(0, 4)], 8) == Report(2, 2, 4), 'fixture 17'
assert solve([Entry(0, 0), Entry(0, 0), Entry(0, 0)], 1) == Report(0, 0, 1), 'fixture 18'
assert solve([Entry(1, 0), Entry(0, 0), Entry(1, 0), Entry(1, 1)], 2) == Report(0, 0, 0), 'fixture 19'
assert solve([Entry(2, 0), Entry(2, 2), Entry(2, 2), Entry(2, 0), Entry(2, 0)], 3) == Report(0, 1, 1), 'fixture 20'
assert solve([Entry(1, 2), Entry(0, 1), Entry(3, 0), Entry(1, 0), Entry(0, 0), Entry(2, 0)], 4) == Report(1, 0, 1), 'fixture 21'
assert solve([Entry(1, 0), Entry(1, 1), Entry(2, 1), Entry(1, 2), Entry(4, 3), Entry(1, 4), Entry(4, 3)], 5) == Report(0, 2, 1), 'fixture 22'
assert solve([Entry(2, 4), Entry(0, 4), Entry(3, 0), Entry(3, 0), Entry(1, 5), Entry(0, 3), Entry(5, 3), Entry(0, 3)], 6) == Report(2, 1, 1), 'fixture 23'
assert solve([Entry(0, 1), Entry(0, 1), Entry(1, 0), Entry(2, 2)], 4) == Report(0, 0, 2), 'fixture 24'
assert solve([Entry(0, 1), Entry(0, 1), Entry(1, 2), Entry(3, 3)], 5) == Report(1, 1, 2), 'fixture 25'
